return static function(PDO $c):string{$steps=array_map('intval',$c->query("SELECT statement_number FROM schema_migration_steps WHERE version='059' ORDER BY statement_number")->fetchAll(PDO::FETCH_COLUMN));if($steps!==[]&&$steps!==range(1,max($steps)))throw new RuntimeException('Migration 059 recovery steps are not a valid completed prefix.');$tables=(int)$c->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN('company_approval_policies','company_approval_decisions')")->fetchColumn();$permissions=(int)$c->query("SELECT COUNT(*) FROM permissions WHERE code IN('administration.approval_policies.view','administration.approval_policies.manage') AND active=TRUE")->fetchColumn();$complete=$tables===2&&$permissions===2;if($steps!==[]&&max($steps)>=3&&!$complete)throw new RuntimeException('Migration 059 recovery metadata does not match the database state.');return$steps===[]&&$complete?'baseline':'apply';};
